=<!DOCTYPE html>
<html>
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <style>
        body { font-family: 'Inter', -apple-system, system-ui, sans-serif; background-color: #f8fafc; color: #1e293b; margin: 0; padding: 0; }
        .wrapper { background-color: #f8fafc; padding: 40px 10px; }
        .container { max-width: 600px; margin: 0 auto; background: #ffffff; border-radius: 16px; overflow: hidden; box-shadow: 0 4px 25px rgba(0,0,0,0.05); border: 1px solid #e2e8f0; }
        .header { background: #0f172a; padding: 40px 20px; text-align: center; }
        .header-tag { color: #818cf8; font-size: 11px; font-weight: 800; letter-spacing: 4px; text-transform: uppercase; margin-bottom: 12px; }
        .header-text { color: #ffffff; font-size: 22px; font-weight: 900; letter-spacing: 2px; text-transform: uppercase; }
        .content { padding: 40px 35px; }
        .badge { display: inline-block; padding: 6px 14px; border-radius: 99px; font-weight: 700; font-size: 11px; text-transform: uppercase; margin-bottom: 30px; }
        .badge-critical { background: #fee2e2; color: #b91c1c; border: 1px solid #f87171; padding: 8px 18px; }
        .badge-high { background: #fffbeb; color: #b45309; border: 1px solid #fbbf24; padding: 8px 18px; }
        .title { font-size: 26px; font-weight: 800; color: #0f172a; margin: 0 0 15px; letter-spacing: -0.5px; }
        .alert-box { background: #f1f5f9; border-radius: 12px; padding: 25px; margin-bottom: 35px; border-left: 4px solid #6366f1; }
        .description { font-size: 17px; color: #334155; line-height: 1.6; margin: 0; }
        .tech-table { width: 100%; border-collapse: collapse; margin-bottom: 35px; }
        .tech-row { border-bottom: 1px solid #f1f5f9; }
        .tech-label { padding: 15px 0; color: #64748b; font-size: 11px; font-weight: 700; text-transform: uppercase; width: 110px; }
        .tech-value { padding: 15px 0; color: #1e293b; font-size: 15px; font-weight: 600; }
        .btn { display: inline-block; background: #6366f1; color: #ffffff !important; text-decoration: none; padding: 18px 40px; border-radius: 10px; font-weight: 700; font-size: 14px; text-transform: uppercase; letter-spacing: 1px; }
        .footer { padding: 30px 20px; text-align: center; color: #94a3b8; font-size: 11px; border-top: 1px solid #f1f5f9; }

        @media only screen and (max-width: 600px) {
            .header { padding: 30px 15px; }
            .content { padding: 30px 20px; }
            .btn { width: 100%; text-align: center; box-sizing: border-box; }
        }
    </style>
</head>
<body>
    <div class="wrapper">
        <div class="container">
            <div class="header" style="border-bottom: 1px solid #1e293b;">
                <div class="header-tag">SOFIA SOLUTIONS | CENTRO DE SEGURIDAD</div>
                <div class="header-text">SISTEMA DE ALERTAS</div>
            </div>

            <div class="content">
                <div class="badge badge-{{ ($json.body?.severity || $json.severity || 'urgent').toLowerCase() === 'high' ? 'high' : 'critical' }}">
                    {{ (($json.body?.title || $json.title || '').toUpperCase().includes('SOS') || ($json.body?.description || $json.description || '').toUpperCase().includes('SOS')) ? '🚨 EMERGENCIA SOS' : (($json.body?.severity || $json.severity || 'urgent').toLowerCase() === 'high' ? '⚠️ ALTA PRIORIDAD' : '🛑 CRÍTICA') }}
                </div>

                <h2 class="title">Incidente Detectado</h2>

                <div class="alert-box">
                    <p class="description">{{ ($json.body?.description || $json.description || 'Se ha detectado un evento de seguridad que requiere revisión.') }}</p>
                </div>

                <table class="tech-table">
                    <tr class="tech-row">
                        <td class="tech-label">Cliente</td>
                        <td class="tech-value">{{ $json.body?.clientName || $json.clientName || 'Global' }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Incidente</td>
                        <td class="tech-value">{{ ($json.body?.title || $json.title || 'Alerta de Seguridad') }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Referencia</td>
                        <td class="tech-value">#SOC-{{ $json.body?.alertId || $json.alertId || '5120' }}</td>
                    </tr>
                    <tr class="tech-row">
                        <td class="tech-label">Fecha/Hora</td>
                        <td class="tech-value">{{ $json.body?.timestamp || $json.timestamp }}</td>
                    </tr>
                </table>

                <div style="text-align: center;">
                    <a href="https://sofia-solutions.serveo.net" class="btn">ACCEDER AL DASHBOARD</a>
                </div>
            </div>

            <div class="footer">
                SISTEMA INTEGRADO DE MONITOREO 24/7<br>
                <span style="font-weight: 700; color: #64748b; margin-top: 5px; display: inline-block;">© 2026 SOFIA SOLUTIONS | SECURITY GROUP</span>
            </div>
        </div>
    </div>
</body>
</html>
